import os,subprocess
from concurrent.futures import ThreadPoolExecutor
H=os.path.expanduser('~')
roots=[os.path.join(H,'Desktop','DEV')]
repos=set([os.path.join(H,'.claude'),os.path.join(H,'.claude','global-memory'),os.path.join(H,'Desktop','SecondBrain')])
base=roots[0]
for dp,dn,fn in os.walk(base):
    depth=dp[len(base):].count(os.sep)
    if '.git' in dn or '.git' in fn: repos.add(dp)
    dn[:]=[d for d in dn if d not in('.git','node_modules','.venv','venv','renv','__pycache__','worktrees','.claude')] if depth<3 else []
# include nested ~/.claude repos
for d in os.listdir(os.path.join(H,'.claude')):
    p=os.path.join(H,'.claude',d)
    if os.path.isdir(os.path.join(p,'.git')) or os.path.isfile(os.path.join(p,'.git')): repos.add(p)
def g(r,*a): 
    x=subprocess.run(['git','-C',r,*a],capture_output=True,text=True,timeout=120); return x.stdout.strip()
def check(r):
    out=[]
    st=g(r,'status','--porcelain=v1').splitlines()
    if st: out.append(f"DIRTY {len(st)}: "+'; '.join(s.strip() for s in st[:6]))
    # branches ahead / no upstream
    for line in g(r,'for-each-ref','--format=%(refname:short)|%(upstream:short)|%(upstream:track)','refs/heads').splitlines():
        b,u,t=(line.split('|')+['',''])[:3]
        if not u: out.append(f"LOCAL-ONLY branch {b}")
        elif 'ahead' in t: out.append(f"UNPUSHED {b} {t}")
    wts=[l[9:] for l in g(r,'worktree','list','--porcelain').splitlines() if l.startswith('worktree ')]
    for w in wts[1:]: out.append(f"WORKTREE {w}")
    st2=g(r,'stash','list').splitlines()
    if st2: out.append(f"STASH x{len(st2)}")
    return r,out
with ThreadPoolExecutor(12) as ex:
    res=list(ex.map(check,sorted(repos)))
print("repos scanned:",len(res))
for r,o in res:
    if o: print(r); [print("   ",x) for x in o]
EOF
